import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Customer","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/customer.md","filePath":"03-developer/models/customer.md"}`),a={name:`03-developer/models/customer.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="customer" tabindex="-1">Customer <a class="header-anchor" href="#customer" aria-label="Permalink to “Customer”">​</a></h1><p><strong>Model purpose:</strong> This model stores the store&#39;s customer information and manages relationships related to purchases, invoices, addresses, support tickets, favorites, comments, and the customer&#39;s financial credit. It also provides information for authentication, categorizing customers based on their purchase history, and recording internal administrator notes.</p><h2 id="table-customers" tabindex="-1">Table: <code>customers</code> <a class="header-anchor" href="#table-customers" aria-label="Permalink to “Table: customers”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique customer identifier</td></tr><tr><td><code>name</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Customer name</td></tr><tr><td><code>email</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Customer email address</td></tr><tr><td><code>email_verified_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time the email address was verified</td></tr><tr><td><code>password</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Customer account password</td></tr><tr><td><code>mobile</code></td><td>VARCHAR(15)</td><td>Yes</td><td>Customer&#39;s mobile phone number</td></tr><tr><td><code>dob</code></td><td>DATE</td><td>Yes</td><td>Customer&#39;s date of birth</td></tr><tr><td><code>sms</code></td><td>VARCHAR(10)</td><td>Yes</td><td>Field related to the SMS authentication code</td></tr><tr><td><code>code</code></td><td>VARCHAR(10)</td><td>Yes</td><td>Field related to the authentication code</td></tr><tr><td><code>colleague</code></td><td>TINYINT(1)</td><td>No</td><td>Indicates whether the customer is a colleague</td></tr><tr><td><code>description</code></td><td>TEXT</td><td>Yes</td><td>Internal administrator note about the customer</td></tr><tr><td><code>credit</code></td><td>DECIMAL(20,2)</td><td>No</td><td>Customer&#39;s financial credit balance</td></tr><tr><td><code>total_purchases</code></td><td>BIGINT</td><td>No</td><td>Number of purchases recorded for the customer</td></tr><tr><td><code>sex</code></td><td>ENUM(&#39;MALE&#39;,&#39;FEMALE&#39;)</td><td>Yes</td><td>Customer&#39;s recorded sex</td></tr><tr><td><code>height</code></td><td>INT</td><td>Yes</td><td>Customer&#39;s height</td></tr><tr><td><code>weight</code></td><td>DECIMAL(8,2)</td><td>Yes</td><td>Customer&#39;s weight</td></tr><tr><td><code>avatar</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Profile image file name or identifier</td></tr><tr><td><code>card</code></td><td>LONGTEXT</td><td>Yes</td><td>Current shopping cart information in JSON format</td></tr><tr><td><code>remember_token</code></td><td>VARCHAR(100)</td><td>Yes</td><td>Token for the remember-me login functionality</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last update</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record soft-deletion time</td></tr></tbody></table><h2 id="additional-field-details" tabindex="-1">Additional Field Details <a class="header-anchor" href="#additional-field-details" aria-label="Permalink to “Additional Field Details”">​</a></h2><ul><li><code>email</code> and <code>mobile</code>: Both have unique constraints in the database; duplicate non-<code>NULL</code> values are not accepted.</li><li><code>email_verified_at</code>: Stores the time the email address was verified.</li><li><code>sms</code> and <code>code</code>: Both are used in the authentication process, but the precise difference between their roles is not clear from the provided code and requires reviewing the authentication logic.</li><li><code>colleague</code>: Indicates whether the customer belongs to the colleagues group. This status may be used for colleague-specific features, such as allowing a temporary address for order delivery.</li><li><code>description</code>: An internal administrator note about the customer, not intended for public display to the customer. It can be used to record administrative notes about interacting with the customer.</li><li><code>credit</code>: Stores the customer&#39;s financial credit balance. Its relationship to transactions in the <a href="./credit.html">Credit</a> model and how this value is updated should be reviewed in the system&#39;s financial logic.</li><li><code>total_purchases</code>: Stores the number of the customer&#39;s purchases and is used by the <code>loyalty()</code> method to determine their loyalty level.</li><li><code>sex</code>, <code>height</code>, and <code>weight</code>: Additional customer information.</li><li><code>avatar</code>: Specifies the customer&#39;s profile image.</li><li><code>card</code>: Stores the customer&#39;s current shopping cart in JSON format and can be used to transfer or restore the cart across platforms, such as a website and mobile app.</li><li><code>deleted_at</code>: Enables soft deletion of the customer.</li></ul><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="hidden" tabindex="-1"><code>$hidden</code> <a class="header-anchor" href="#hidden" aria-label="Permalink to “$hidden”">​</a></h3><p>Hides the <code>password</code> and <code>remember_token</code> fields from the model&#39;s standard serialized output, such as when converting it to an array or JSON.</p><h3 id="casts" tabindex="-1"><code>$casts</code> <a class="header-anchor" href="#casts" aria-label="Permalink to “$casts”">​</a></h3><p>Casts <code>email_verified_at</code> to <code>datetime</code> and <code>dob</code> to <code>date</code>.</p><h3 id="invoices" tabindex="-1"><code>invoices()</code> <a class="header-anchor" href="#invoices" aria-label="Permalink to “invoices()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <a href="./invoice.html">Invoice</a> model and returns the invoices belonging to the customer.</p><h3 id="tickets" tabindex="-1"><code>tickets()</code> <a class="header-anchor" href="#tickets" aria-label="Permalink to “tickets()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <a href="./ticket.html">Ticket</a> model and returns all tickets associated with the customer, including main tickets and replies.</p><h3 id="main-tickets" tabindex="-1"><code>main_tickets()</code> <a class="header-anchor" href="#main-tickets" aria-label="Permalink to “main_tickets()”">​</a></h3><p>Retrieves the customer&#39;s tickets where <code>parent_id IS NULL</code>. This method is used to access main or parent tickets, meaning tickets that initiate a support conversation.</p><h3 id="products" tabindex="-1"><code>products()</code> <a class="header-anchor" href="#products" aria-label="Permalink to “products()”">​</a></h3><p>Defines a many-to-many (<code>belongsToMany</code>) relationship with the <a href="./product.html">Product</a> model through the <code>customer_product</code> pivot table.</p><h3 id="addresses" tabindex="-1"><code>addresses()</code> <a class="header-anchor" href="#addresses" aria-label="Permalink to “addresses()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <a href="./address.html">Address</a> model and returns the addresses associated with the customer.</p><h3 id="favorites" tabindex="-1"><code>favorites()</code> <a class="header-anchor" href="#favorites" aria-label="Permalink to “favorites()”">​</a></h3><p>Defines a many-to-many relationship with the <code>Product</code> model through the <code>customer_product</code> pivot table and is used to access the customer&#39;s favorite products.</p><p><strong>Note:</strong> This method uses the same pivot table as the <code>products()</code> method. The semantic difference between these methods depends on the pivot table structure and how it is used in the application.</p><h3 id="comments" tabindex="-1"><code>comments()</code> <a class="header-anchor" href="#comments" aria-label="Permalink to “comments()”">​</a></h3><p>Defines a polymorphic (<code>morphMany</code>) relationship with the <a href="./comment.html">Comment</a> model and returns the comments authored by the customer.</p><h3 id="evaluations" tabindex="-1"><code>evaluations()</code> <a class="header-anchor" href="#evaluations" aria-label="Permalink to “evaluations()”">​</a></h3><p>Retrieves related evaluations from the <a href="./evaluation.html">Evaluation</a> model. The results include three groups: public evaluations without a specific association, evaluations of type <code>Customer</code> without a specified identifier, and evaluations specific to this customer.</p><h3 id="avatar" tabindex="-1"><code>avatar()</code> <a class="header-anchor" href="#avatar" aria-label="Permalink to “avatar()”">​</a></h3><p>Returns the URL of the customer&#39;s profile image. If <code>avatar</code> is empty or <code>NULL</code>, the default image <code>assets/default/unknown.svg</code> is provided; otherwise, the file URL is built from the <code>customers/</code> storage path.</p><h3 id="purchased-products" tabindex="-1"><code>purchased_products()</code> <a class="header-anchor" href="#purchased-products" aria-label="Permalink to “purchased_products()”">​</a></h3><p>Retrieves the identifiers of products purchased by the customer by joining the <code>orders</code> and <code>invoices</code> tables. Only invoices with the <code>PAID</code>, <code>COMPLETED</code>, or <code>PROCESSING</code> statuses are included. The output contains <code>product_id</code> identifiers, not complete product models.</p><h3 id="hasrole" tabindex="-1"><code>hasRole()</code> <a class="header-anchor" href="#hasrole" aria-label="Permalink to “hasRole()”">​</a></h3><p>In the current version, always returns <code>false</code>. Therefore, this method currently confirms no roles for the customer.</p><h3 id="credits" tabindex="-1"><code>credits()</code> <a class="header-anchor" href="#credits" aria-label="Permalink to “credits()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <a href="./credit.html">Credit</a> model and returns the credit transactions associated with the customer.</p><h3 id="credithistory" tabindex="-1"><code>creditHistory()</code> <a class="header-anchor" href="#credithistory" aria-label="Permalink to “creditHistory()”">​</a></h3><p>Retrieves the customer&#39;s credit transactions through a <code>hasMany</code> relationship and sorts them by <code>created_at</code> in descending order, placing newer records first.</p><h3 id="getformattedcreditattribute" tabindex="-1"><code>getFormattedCreditAttribute()</code> <a class="header-anchor" href="#getformattedcreditattribute" aria-label="Permalink to “getFormattedCreditAttribute()”">​</a></h3><p>Formats the customer&#39;s <code>credit</code> value using <code>number_format()</code> and makes it available as the computed <code>formatted_credit</code> attribute.</p><h3 id="hassufficientcredit-int-amount-bool" tabindex="-1"><code>hasSufficientCredit(int $amount): bool</code> <a class="header-anchor" href="#hassufficientcredit-int-amount-bool" aria-label="Permalink to “hasSufficientCredit(int $amount): bool”">​</a></h3><p>Checks whether the customer&#39;s credit balance is greater than or equal to the required amount. Returns <code>true</code> if <code>credit &gt;= amount</code>; otherwise, returns <code>false</code>.</p><h3 id="loyalty" tabindex="-1"><code>loyalty()</code> <a class="header-anchor" href="#loyalty" aria-label="Permalink to “loyalty()”">​</a></h3><p>Determines the customer&#39;s level based on the value of <code>total_purchases</code>:</p><ul><li>Fewer than 2 purchases: <code>new</code></li><li>More than 5 purchases: <code>loyal</code></li><li>From 2 to 5 purchases, inclusive: <code>regular</code></li></ul><h3 id="unsuccessinvoices" tabindex="-1"><code>unsuccessInvoices()</code> <a class="header-anchor" href="#unsuccessinvoices" aria-label="Permalink to “unsuccessInvoices()”">​</a></h3><p>Retrieves the customer&#39;s invoices through the <code>invoices()</code> relationship and returns only those with the <code>PENDING</code>, <code>CANCELED</code>, or <code>FAILED</code> status. This method provides a filtered relationship for accessing unpaid, canceled, or failed invoices.</p>`,47)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};